import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
S=json.load(open('/app/output/spec.json'))
JN=S['proprio']['joints']; POS=np.array(S['proprio']['position_m']); AX=np.array(S['proprio']['axis'])
AN=S['action_types']['joint_position']['layout']; RANGES=np.array(S['action_types']['joint_position']['range_rad'])
CHAINS={
 'left':[10,11,12,13,14,15,16,17],
 'right':[10,40,41,42,43,44,45,46],
 'left_leg':list(range(5)), 'right_leg':list(range(5,10))}
def transform(q,chain):
 T=np.eye(4)
 for i in chain:
  R=Rotation.from_rotvec(AX[i]*q[i]).as_matrix();M=np.eye(4);M[:3,:3]=R;M[:3,3]=POS[i]-R@POS[i];T=T@M
 return T

def point(q,chain,p):
 T=transform(q,chain);return T[:3,:3]@p+T[:3,3]
def palm(q,side):
 return point(q,CHAINS[side],np.array([.425,.214 if side=='left' else -.214,.087]))
def arm_ik(q,side,target,orientation=None):
 inds=CHAINS[side][1:]; init=q[inds].copy();
 lo=[];hi=[]
 for i in inds:
  name=JN[i]; name=name.replace('lh_','lh_A_').replace('rh_','rh_A_'); a=AN.index(name);lo.append(RANGES[a,0]);hi.append(RANGES[a,1])
 def residual(v):
  qq=q.copy();qq[inds]=v; e=list((palm(qq,side)-target)*10)
  if orientation is not None:
   e.extend((transform(qq,CHAINS[side])[:3,:3]-orientation).flatten()*.5)
  e.extend((v-init)*.025);return e
 sol=least_squares(residual,np.clip(init,lo,hi),bounds=(lo,hi),max_nfev=200)
 out=q.copy();out[inds]=sol.x
 return out,palm(out,side),sol.cost

def actions(q):
 a=[]
 for n in AN:
  j=n.replace('_A_','_')
  if j.endswith('J0'):v=q[JN.index(j[:-1]+'1')]+q[JN.index(j[:-1]+'2')]
  else:v=q[JN.index(j)]
  a.append(v)
 return np.clip(2*(np.array(a)-RANGES[:,0])/(RANGES[:,1]-RANGES[:,0])-1,-1,1)
