"""Public-client kitchen controller and action record; no resets.
Invoke `python gen.py move command.json` for an observed motion,
`python gen.py replay` to replay the recorded targets on a fresh service.
"""
import json,sys
from pathlib import Path
import numpy as np
from PIL import Image
from rcb_client import Robot
from geometry import actions,arm_ik,JN,palm
ROOT=Path('/app/output')
def save(o):
 k=o.meta['control_steps'];d=ROOT/f'obs_{k:03d}';o.save(str(d))
 for c,a in o.last.items():Image.fromarray(a).save(str(d/(c+'.png')))
 (ROOT/'latest.json').write_text(json.dumps(o.meta));
 print('step',k,'done',o.meta['done'],'reason',o.meta['reason']);p=np.array(o.meta['proprio']['now']);print('body',np.round(p[:16],3),'right',np.round(p[40:47],3),'imu',np.round(p[-6:],3))

def main():
 r=Robot();s=r.spec();o=r.get_obs(video='none');
 if len(sys.argv)<2:save(o);return
 if sys.argv[1]=='replay':
  for line in (ROOT/'actions.jsonl').read_text().splitlines():
   rec=json.loads(line);o=r.submit('joint_position',rec['actions'],video='none');
   if o.done:break
  save(o);return
 cmd=json.load(open(sys.argv[2]));q=np.array(o.meta['proprio']['now'][:69]);
 if (ROOT/'target.npy').exists():base=np.load(ROOT/'target.npy')
 else:base=q.copy()
 target=base.copy()
 for name,val in cmd.get('joints',{}).items():target[JN.index(name)]=val
 for side,pos in cmd.get('palms',{}).items():
  target,actual,cost=arm_ik(target,side,np.array(pos));print(side,'target reached',actual,'cost',cost)
 n=cmd.get('steps',10);ramp=cmd.get('ramp',n)
 aa=[]
 for i in range(n):
  t=min((i+1)/ramp,1);v=base*(1-t)+target*t;aa.append(actions(v).tolist())
 with (ROOT/'actions.jsonl').open('a') as f:f.write(json.dumps({'command':cmd,'actions':aa})+'\n')
 np.save(ROOT/'target.npy',target)
 o=r.submit('joint_position',aa,video='frames',video_fps=25,note=cmd.get('note',''))
 save(o)
if __name__=='__main__':main()
